    17	        *) ;;
    18	    esac
    19	}
    20	sprint_body() {
    21	    printf '### Sprint Goal\ng\n\n### Deliverables\n- [ ] d\n\n### Acceptance Criteria\n- [ ] c\n\n'
    22	    printf '### Technical Tasks\n- [ ] Task %s → **[G-1]**\n\n' "$2"
    23	    seams_block "$1"
    24	    printf '### Dependencies\n- none\n\n### Security Considerations\n- none\n\n'
    25	    printf '### Risks & Mitigation\n| Risk | Probability | Impact | Mitigation |\n|---|---|---|---|\n| r | Low | Low | m |\n\n'
    26	    printf '### Success Metrics\n- m\n\n'
    27	}
    28	plan() {
    29	    printf '# Sprint Plan: x\n\n**Version:** 1.0\n'
    30	    [[ -n "$1" ]] && printf '**Date:** %s\n' "$1"
    31	    printf '**Author:** test\n\n---\n\n'
    32	    printf '## Sprint 1: Foundation\n\n'; sprint_body "$2" "1.1"
